import java.util.*; class Solution { private Map<Integer, List<Integer>> charPositions; private Integer[][] memo; private int n; private int m; public int findRotateSteps(String ring, String key) { n = ring.length(); m = key.length(); charPositions = new HashMap<>(); for (int i = 0; i < n; i++) { charPositions.computeIfAbsent(ring.charAt(i) - 'a', k -> new ArrayList<>()).add(i); } memo = new Integer[m][n]; return solve(0, 0, key); } private int solve(int keyIdx, int ringIdx, String key) { if (keyIdx == m) return 0; if (memo[keyIdx][ringIdx] != null) return memo[keyIdx][ringIdx]; int minSteps = Integer.MAX_VALUE; int targetChar = key.charAt(keyIdx) - 'a'; for (int nextRingIdx : charPositions.get(targetChar)) { int dist = Math.abs(nextRingIdx - ringIdx); int steps = Math.min(dist, n - dist); minSteps = Math.min(minSteps, steps + 1 + solve(keyIdx + 1, nextRingIdx, key)); } return memo[keyIdx][ringIdx] = minSteps; } }